<?php
namespace App\Http\Controllers\Tenant;use App\Domain\AI\Agents\Models\Agent;use App\Domain\AI\Knowledge\Models\KnowledgeSourceVersion;use App\Domain\AI\Knowledge\Services\{AttachKnowledgeToAgentVersionService,DetachKnowledgeFromAgentVersionService};use App\Http\Controllers\Controller;use App\Http\Requests\Tenant\EmptyKnowledgeMutationRequest;use App\Http\Support\AiLaunchpadHttpGate;use Illuminate\Validation\ValidationException;
final class AiAgentKnowledgeController extends Controller{public function attach(EmptyKnowledgeMutationRequest$r,Agent$agent,KnowledgeSourceVersion$knowledgeVersion,AiLaunchpadHttpGate$g,AttachKnowledgeToAgentVersionService$s){$g->ensure($r->user());$g->assertCurrentTenant($agent);$g->assertCurrentTenant($knowledgeVersion);try{$s->attach($r->user(),$agent,$knowledgeVersion);}catch(\DomainException){throw ValidationException::withMessages(['knowledge'=>'Este conocimiento no puede vincularse.']);}return redirect()->route('tenant.admin.ai-agents.show',$agent)->with('success','Conocimiento vinculado al borrador.');}public function detach(EmptyKnowledgeMutationRequest$r,Agent$agent,KnowledgeSourceVersion$knowledgeVersion,AiLaunchpadHttpGate$g,DetachKnowledgeFromAgentVersionService$s){$g->ensure($r->user());$g->assertCurrentTenant($agent);$g->assertCurrentTenant($knowledgeVersion);$s->detach($r->user(),$agent,$knowledgeVersion);return redirect()->route('tenant.admin.ai-agents.show',$agent)->with('success','Conocimiento desvinculado del borrador.');}}
